import { createServer } from 'dhcp';

const keys = new Map([
    ['client-1', {
        secretId: 1,
        secret: Buffer.from(process.env.DHCP_CLIENT_1_KEY ?? '', 'hex'),
    }],
]);

if (keys.get('client-1').secret.length === 0) {
    throw new Error('Set DHCP_CLIENT_1_KEY to a hex-encoded per-client secret');
}

const server = createServer({
    range: ['192.168.1.10', '192.168.1.99'],
    server: '192.168.1.1',
    authentication: {
        mode: 'delayed',
        required: true,
        getKey(packet, secretId) {

            const key = typeof packet.clientId === 'string' ? keys.get(packet.clientId) : undefined;

            return key && (secretId === undefined || secretId === key.secretId) ? key : undefined;
        },
    },
});

server.on('authenticationFailed', (reason, packet) => {

    console.warn(`Rejected ${packet.chaddr}: ${reason}`);
});

server.listen();
